import AVFoundation
import CoreVideo
import Foundation

// d33: does AVAssetImageGenerator with a custom compositor answering Frame Job's
// attributes hand back a 16-bit image of a 10-bit HEVC or ProRes source when an
// 8-bit H.264 track sits beside it?

final class Inst: NSObject, AVVideoCompositionInstructionProtocol {
    let timeRange: CMTimeRange
    let enablePostProcessing = false
    let containsTweening = true
    let requiredSourceTrackIDs: [NSValue]?
    let passthroughTrackID = kCMPersistentTrackID_Invalid
    init(_ r: CMTimeRange, _ ids: [Int32]) {
        timeRange = r
        requiredSourceTrackIDs = ids.map { NSNumber(value: $0) }
    }
}

final class Comp: NSObject, AVVideoCompositing {
    var sourcePixelBufferAttributes: [String: any Sendable]? {
        [kCVPixelBufferPixelFormatTypeKey as String: Int(REDACTED),
         kCVPixelBufferMetalCompatibilityKey as String: true]
    }
    var requiredPixelBufferAttributesForRenderContext: [String: any Sendable] {
        [kCVPixelBufferPixelFormatTypeKey as String: Int(REDACTED),
         kCVPixelBufferMetalCompatibilityKey as String: true]
    }
    var canConformColorOfSourceFrames: Bool { false }
    var supportsHDRSourceFrames: Bool { false }
    func renderContextChanged(_ c: AVVideoCompositionRenderContext) {}
    func startRequest(_ r: AVAsynchronousVideoCompositionRequest) {
        guard let out = r.renderContext.newPixelBuffer() else {
            r.finish(with: NSError(domain: "p", code: 1)); return
        }
        r.finish(withComposedVideoFrame: out)
    }
    func cancelAllPendingVideoCompositionRequests() {}
}

func video(_ path: String) -> AVAssetTrack {
    let a = AVURLAsset(url: URL(fileURLWithPath: path))
    return a.tracks(withMediaType: .video)[0]
}

struct Seg { let file: String; let at: Double; let len: Double }

func run(_ name: String, tracks: [[Seg]], instr: [(Double, Double, [Int32])], t: Double) {
    let c = AVMutableComposition()
    for (i, segs) in tracks.enumerated() {
        let tr = c.addMutableTrack(withMediaType: .video, preferredTrackID: Int32(i + 1))!
        for s in segs {
            let src = video(s.file)
            try! tr.insertTimeRange(
                CMTimeRange(start: .zero, duration: CMTime(seconds: s.len, preferredTimescale: 600)),
                of: src, at: CMTime(seconds: s.at, preferredTimescale: 600))
        }
    }
    let ins = instr.map {
        Inst(CMTimeRange(start: CMTime(seconds: $0.0, preferredTimescale: 600),
                         duration: CMTime(seconds: $0.1, preferredTimescale: 600)), $0.2)
    }
    let cfg = AVVideoComposition.Configuration(
        colorPrimaries: AVVideoColorPrimaries_ITU_R_709_2,
        colorTransferFunction: AVVideoTransferFunction_ITU_R_709_2,
        colorYCbCrMatrix: AVVideoYCbCrMatrix_ITU_R_709_2,
        customVideoCompositorClass: Comp.self,
        frameDuration: CMTime(value: 1, timescale: 30),
        instructions: ins, renderScale: 1, renderSize: CGSize(width: 640, height: 360))
    let g = AVAssetImageGenerator(asset: c)
    g.videoComposition = AVVideoComposition(configuration: cfg)
    g.requestedTimeToleranceBefore = .zero
    g.requestedTimeToleranceAfter = .zero
    g.appliesPreferredTrackTransform = false
    do {
        let img = try g.copyCGImage(at: CMTime(seconds: t, preferredTimescale: 600), actualTime: nil)
        print("\(name): bpc=\(img.bitsPerComponent) bpp=\(img.bitsPerPixel) float=\(img.bitmapInfo.contains(.floatComponents))")
    } catch {
        print("\(name): error \(error)")
    }
}

let d = CommandLine.arguments[1]
let h10 = d + "/hevc10.mov", h8 = d + "/h264.mov", pr = d + "/prores.mov", h8h = d + "/hevc8.mov"

run("A  HEVC10 alone", tracks: [[Seg(file: h10, at: 0, len: 2)]], instr: [(0, 2, [1])], t: 1)
run("A2 ProRes alone", tracks: [[Seg(file: pr, at: 0, len: 2)]], instr: [(0, 2, [1])], t: 1)
run("A3 H264 alone", tracks: [[Seg(file: h8, at: 0, len: 2)]], instr: [(0, 2, [1])], t: 1)
run("B  HEVC10 + H264 both on frame", tracks: [[Seg(file: h10, at: 0, len: 2)], [Seg(file: h8, at: 0, len: 2)]],
    instr: [(0, 2, [1, 2])], t: 1)
run("B2 ProRes + H264 both on frame", tracks: [[Seg(file: pr, at: 0, len: 2)], [Seg(file: h8, at: 0, len: 2)]],
    instr: [(0, 2, [1, 2])], t: 1)
run("B3 HEVC10 + HEVC8 both on frame", tracks: [[Seg(file: h10, at: 0, len: 2)], [Seg(file: h8h, at: 0, len: 2)]],
    instr: [(0, 2, [1, 2])], t: 1)
run("C  HEVC10 + ProRes both on frame", tracks: [[Seg(file: h10, at: 0, len: 2)], [Seg(file: pr, at: 0, len: 2)]],
    instr: [(0, 2, [1, 2])], t: 1)
run("D  one track, HEVC10 then H264, frame on HEVC10", tracks: [[Seg(file: h10, at: 0, len: 2), Seg(file: h8, at: 2, len: 2)]],
    instr: [(0, 2, [1]), (2, 2, [1])], t: 1)
run("D2 one track, H264 then HEVC10, frame on HEVC10", tracks: [[Seg(file: h8, at: 0, len: 2), Seg(file: h10, at: 2, len: 2)]],
    instr: [(0, 2, [1]), (2, 2, [1])], t: 3)
run("E  two tracks, H264 later on track 2, frame shows HEVC10 only, required [1]",
    tracks: [[Seg(file: h10, at: 0, len: 2)], [Seg(file: h8, at: 2, len: 2)]],
    instr: [(0, 2, [1]), (2, 2, [2])], t: 1)
run("E2 two tracks overlap, required [1] only at frame",
    tracks: [[Seg(file: h10, at: 0, len: 2)], [Seg(file: h8, at: 0, len: 2)]],
    instr: [(0, 2, [1])], t: 1)

